const inputData = $input.first().json;

// Webinar date (IST)
const webinarDateStr = inputData["Webinar Date and Time (YYYY-MM-DD HH:MM)"];

// Force today's date in IST regardless of server timezone
const nowUTC = new Date();
const istOffsetMs = 5.5 * 60 * 60 * 1000;
const todayIST = new Date(nowUTC.getTime() + istOffsetMs);

// Get IST date string and rebuild as midnight IST
const istDateStr = todayIST.toISOString().slice(0, 10);
let todayISTMidnight = new Date(istDateStr + "T00:00:00+05:30");

// Weekend adjustment: if today is Saturday (6), treat as Friday (shift back 1 day)
const dayOfWeek = todayISTMidnight.getDay();
if (dayOfWeek === 6) {
  todayISTMidnight = new Date(todayISTMidnight.getTime() - 1 * 24 * 60 * 60 * 1000);
}

// Webinar day at midnight IST
const webinarDateOnly = webinarDateStr.slice(0, 10);
const webinarDay = new Date(webinarDateOnly + "T00:00:00+05:30");

// Diff in days
const diffMs = todayISTMidnight.getTime() - webinarDay.getTime();
const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

return [{
  json: {
    day: diffDays
  }
}];

const inputData = $input.first().json;

// Webinar date (IST)
const webinarDateStr = inputData["Webinar Date and Time (YYYY-MM-DD HH:MM)"];

// Force today's date in IST regardless of server timezone
const nowUTC = new Date();
const istOffsetMs = 5.5 * 60 * 60 * 1000;
const todayIST = new Date(nowUTC.getTime() + istOffsetMs);

// Get IST date string and rebuild as midnight IST
const istDateStr = todayIST.toISOString().slice(0, 10); // "YYYY-MM-DD"
const todayISTMidnight = new Date(istDateStr + "T00:00:00+05:30");

// Webinar day at midnight IST
const webinarDay = new Date(webinarDateStr + ":00+05:30");
webinarDay.setHours(0, 0, 0, 0);

// Diff in days (negative = before webinar, positive = after)
const diffMs = todayISTMidnight.getTime() - webinarDay.getTime();
const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

// Map diffDays to reminder label and drive link key
const reminderMap = {
  "-7": { label: "Day(-7)", key: "Drive link Day(-7)" },
  "-6": { label: "Day(-6)", key: "Drive link Day(-6)" },
  "-5": { label: "Day(-5)", key: "Drive link Day(-5)" },
  "-4": { label: "Day(-4)", key: "Drive link Day(-4)" },
  "-3": { label: "Day(-3)", key: "Drive link Day(-3)" },
  "-2": { label: "Day(-2)", key: "Drive link Day(-2)" },
  "-1": { label: "Day(-1)", key: "Drive link Day(-1)" },
   "0": { label: "Day(0)",  key: "Drive link Day(0)"  },
   "1": { label: "Day(+1)", key: "Drive link Day(+1)" },
   "2": { label: "Day(+2)", key: "Drive link Day(+2)" },
};

const match = reminderMap[String(diffDays)];

// If today is not a reminder day, return null
if (!match) {
  return [{ json: { reminder_for: null, drive_link: null, message: "No reminder to send today" } }];
}

const driveLink = inputData[match.key];

return [{
  json: {
    reminder_for: match.label,
    drive_link: driveLink,
    webinar_date: webinarDateStr,
    days_diff: diffDays
  }
}];

